const $=s=>document.querySelector(s);
const icons={wifi:'<path d="M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0M9 16a5 5 0 0 1 6 0"/><circle cx="12" cy="20" r=".5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6zM8 12l3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',phone:'<rect x="7" y="2" width="10" height="20" rx="2"/><path d="M10 18h4"/>',laptop:'<rect x="4" y="3" width="16" height="13" rx="2"/><path d="M2 20h20M6 16l-4 4M18 16l4 4"/>',tv:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8M12 17v4"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',home:'<path d="m3 10 9-7 9 7v11H3zM9 21v-8h6v8"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.wifi}</svg>`;
const devices=[['Alex’s iPhone','Phone','phone'],['Sam’s iPhone','Phone','phone'],['Alex’s MacBook','Laptop','laptop'],['Sam’s laptop','Laptop','laptop'],['Living room TV','Smart TV','tv'],['Home iPad','Tablet','phone'],['Bedroom speaker','Smart speaker','wifi'],['Kitchen speaker','Smart speaker','wifi'],['Game console','Console','tv'],['Smart lighting bridge','Home device','home'],['Video doorbell','Home device','home']];
let state={end:0,allowance:0,view:'hub',screen:'home',connected:true,events:[],purchases:0,source:'extra'};
try{const saved=JSON.parse(sessionStorage.getItem('hush-state'));if(saved)state={...state,...saved,screen:'home'}}catch{}
const active=()=>state.end>Date.now();
const seconds=()=>Math.max(0,Math.ceil((state.end-Date.now())/1000));
const clock=()=>{let s=seconds();return `${String(Math.floor(s/3600)?Math.floor(s/3600):Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s/3600)?Math.floor(s%3600/60):s%60).padStart(2,'0')}`};
const monthlyLeft=()=>state.allowance?20:active()&&state.source==='monthly'?Math.ceil(seconds()/360)/10:0;
const monthlyUsed=()=>Math.round((20-monthlyLeft())*10)/10;
const save=()=>{try{sessionStorage.setItem('hush-state',JSON.stringify(state))}catch{}};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function setView(view){state.view=view;state.screen='home';save();render()}
function render(){const views={hub:hub,laptop:laptop,report:report};$('#main').innerHTML=views[state.view]();document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));bind();save()}
function hub(){return `<section class="hero fade"><div class="intro"><div class="eyebrow">THE HOME PRIVACY ROUTER</div><h1>Some things<br>are just <em>yours.</em></h1><p>Your home is connected.<br>Choose when your private life isn’t.</p><div class="rule"></div><div class="micro"><strong>One home. Eleven devices.</strong><br>Twenty Private Hours, shared each month.<br>A little time to keep things to yourself.</div></div><div class="device-stage"><div class="router"><div class="router-top" aria-hidden="true">${'<span class="vent"></span>'.repeat(20)}</div><div class="display"><div class="display-head"><span class="mini-logo">HUSH</span><span class="network-badge"><i class="dot"></i> Home Wi-Fi ${icon('wifi')}</span></div><div class="screen-body" id="deviceScreen">${screen()}</div><div class="screen-foot"><span>HUSH HOME · 11 DEVICES</span><button data-action="devices">View devices ↗</button></div></div><div class="hardware"><span class="hardware-logo">HUSH</span><span class="led"><i class="led-light ${active()?'on':''}"></i> WI-FI ${active()?'· PRIVATE':'· CONNECTED'}</span></div></div><div class="base"></div><div class="device-caption">${icon('home')} Your household’s privacy, on the meter.</div></div></section><section class="bottom-strip"><div class="fact">${icon('wifi')}<div><strong>One network. All your devices.</strong><p>Protection follows the devices on HUSH Wi-Fi.</p></div></div><div class="fact">${icon('clock')}<div><strong>Private time is shared time.</strong><p>One hour covers your whole connected home.</p></div></div><div class="fact">${icon('shield')}<div><strong>For what happens next.</strong><p>New protection doesn’t erase an existing profile.</p></div></div></section>`}
function screen(){if(state.screen==='devices')return `<div class="sub-head"><button class="back" data-action="home" aria-label="Back to home">‹</button> Connected devices <small>11</small></div><p class="sub-copy">${active()?'New tracking is temporarily blocked':'Wi-Fi is online. Private protection is off.'}</p>${devices.map(([name,type,i])=>`<div class="screen-list"><div>${icon(i)}<span>${name}<span class="device-type">${type}</span></span></div><span class="pill">${active()?'Protected':'Online'}</span></div>`).join('')}`;
if(state.screen==='details')return `<div class="sub-head"><button class="back" data-action="home" aria-label="Back to home">‹</button> Your Private Hours</div><p class="sub-copy">${active()?'Your household is on private time. All 11 connected devices share this session.':state.allowance?'Your monthly allowance has renewed. Start protection when you need it.':'You’ve used this month’s Private Hours. Your Wi-Fi stays on. New tracking and profile sharing have resumed.'}</p><div class="screen-list"><span>Included each month</span><span>20 h</span></div><div class="screen-list"><span>Monthly hours used</span><span>${monthlyUsed()} / 20 h</span></div><div class="screen-list"><span>Allowance renews</span><span>${state.allowance?'Next month':'In 3 days'}</span></div><div class="screen-list"><span>Connected devices</span><span>11</span></div><p class="sub-copy">One hour protects the whole home. Previously collected information stays with the services that received it.</p><button class="screen-btn" data-action="${active()?'home':state.allowance?'start':'buy'}">${active()?'Back to your session':state.allowance?'Start Private Protection':'Start 1 Private Hour · $3.99'}</button>${!active()?'<button class="screen-secondary" data-action="wait">Continue without protection →</button>':''}`;
return `<div class="screen-label"><span>PRIVATE HOURS</span><button class="screen-secondary" style="width:auto;padding:0" data-action="details" aria-label="View Private Hours details">ⓘ</button></div><div class="timer ${active()?'active':''}" id="timer">${active()?clock():state.allowance?'20:00':'00:00'}</div><p class="remaining">${active()?'remaining in this session':state.allowance?'hours available this month':'remaining this month'}</p><div class="meter"><span id="meterFill" style="width:${active()?seconds()/(state.source==='monthly'?72000:3600)*100:state.allowance?100:0}%"></span></div><div class="usage-line"><span>${monthlyUsed()} / 20 monthly hours used</span><span>${state.allowance?'Allowance renewed':'Renews in 3 days'}</span></div><div class="status-box ${active()?'on':''}">${icon(active()?'shield':'lock')}<div><strong>${active()?'Private protection is on':'Private protection is off'}</strong><small>${active()?'New tracking & profile sharing blocked':'Your Wi-Fi is still connected'}</small></div></div><button class="screen-btn" data-action="${active()?'laptop':state.allowance?'start':'buy'}">${active()?'Use your private time →':state.allowance?'Start Private Protection':'Start 1 Private Hour'}${!active()&&!state.allowance?'<span>· $3.99</span>':''}</button><button class="screen-secondary" data-action="${active()?'details':'wait'}">${active()?'View session details':'Continue without protection →'}</button>`}
function laptop(){const protectedNow=active()&&state.connected;return `<section class="page-wrap fade"><div class="page-top"><div><div class="eyebrow">A MOMENT ON YOUR OWN</div><h1>Is this worth one Private Hour?</h1><p>A connected browser, an ordinary search. Watch what changes when protection is on.</p></div><button class="connection" data-action="network"><i class="dot"></i>${state.connected?'HUSH Home Wi-Fi':'Other network'} ▾</button></div><div class="laptop-grid"><div class="browser"><div class="browser-bar"><i class="browser-dot"></i><i class="browser-dot"></i><i class="browser-dot"></i><div class="address">${state.connected?'HUSH Home Wi-Fi':'Other network'} / Connected browser</div></div><div class="browser-status ${protectedNow?'on':''}"><span>${protectedNow?'Private protection ON · '+clock():state.connected?'Private protection OFF · No active private session':'Outside HUSH · Not protected'}</span><button data-action="${protectedNow?'session':'buy'}">${protectedNow?'View session':'Get protection'}</button></div><div class="search-area"><div class="search-logo">elsewhere.</div><form class="search-form" id="searchForm">${icon('search')}<input id="searchInput" aria-label="Simulated search query" placeholder="Something you’d like to keep to yourself…" maxlength="140" required autocomplete="off"><button type="submit">Search</button></form><p class="search-hint">A simulated browser. Your search never leaves this prototype.</p><div id="searchResult"></div></div></div><aside class="activity"><h2>The trail you leave.</h2><p>Activity in this fictional connected-services network. Protection affects new events, not what’s already been shared.</p><div id="events">${events()}</div>${!protectedNow?'<button class="primary wide" data-action="buy">Start 1 Private Hour · $3.99</button>':''}<div class="note">HUSH covers devices on its Wi-Fi during active Private Hours. Information you deliberately submit to a service is still sent to that service.</div></aside></div></section>`}
function escapeHTML(v){return v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function events(){if(!state.events.length)return `<div class="empty">${icon('globe')}<br>No searches in this demonstration yet.<br>Your next search starts the story.</div>`;return state.events.slice().reverse().map(e=>`<div class="event"><div class="event-head">${icon(e.protected?'shield':'globe')}${e.protected?'New profile sharing blocked':'Browsing signal shared'}</div><p>${e.protected?'Session protected this new activity. No query was added to the demonstration ledger.':`“${escapeHTML(e.query)}”<br>Added to connected profile services.`}</p><small>${e.time} · ${e.protected?'Private session':e.network?'HUSH Wi-Fi · Protection off':'Other network · Outside HUSH'}</small>${!e.protected&&active()?'<small>Previously shared · not removed by current protection</small>':''}</div>`).join('')}
function report(){return `<section class="page-wrap fade"><div class="page-top"><div><div class="eyebrow">YOUR HOUSEHOLD STATEMENT</div><h1>A month of connected living.</h1><p>Private time, measured alongside everything else at home.</p></div><span class="connection">Current billing cycle</span></div><div class="report"><div class="report-heading"><h2>HUSH HOME / MONTHLY PRIVACY REPORT</h2><span>ACCOUNT •••• 2046</span></div><div class="report-numbers"><div><small>Private Hours included</small><strong>20<span>h</span></strong></div><div><small>Monthly hours used</small><strong>${monthlyUsed()}<span>h</span></strong></div><div><small>Monthly allowance left</small><strong>${monthlyLeft()}<span>h</span></strong></div><div><small>Next renewal</small><strong>${state.allowance?'30':'3'}<span>days</span></strong></div></div><div class="report-body"><div><h3>Tracking requests detected · 1,284</h3><div class="chart" aria-label="Illustrative monthly tracking activity bar chart">${[31,46,25,67,44,54,79,48,35,65,72,40,62,88,74,57,83,68,98,63,70,89,76,60,83,95,73,87].map(v=>`<i class="bar" style="height:${v}%"></i>`).join('')}</div><div class="chart-labels"><span>Week 1</span><span>Week 2</span><span>Week 3</span><span>Week 4</span></div><p class="note">Detected requests are not the same as successfully shared data. Protected activity contents are not recorded in this report.</p></div><div><h3>By request category</h3>${[['App data requests','438'],['Browser profiling','327'],['Device data sharing','291'],['Location & movement','155'],['Other','73']].map(([a,b])=>`<div class="category"><span>${a}</span><span>${b}</span></div>`).join('')}<div class="category"><span>Advertising profile updates*</span><span>63</span></div><p class="note">*A separate outcome measure, not an additional request category.</p></div></div><div class="report-bottom"><p>11 connected devices · ${state.purchases} additional hour${state.purchases===1?'':'s'} purchased in this demonstration.<br>Extra hours protect future sessions. Existing profiles are not removed.</p><button class="primary" data-action="${active()?'session':'buy'}">${active()?'View active session':'Add 1 Private Hour · $3.99'}</button></div></div></section>`}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));const form=$('#searchForm');if(form)form.onsubmit=e=>{e.preventDefault();const query=$('#searchInput').value.trim();if(!query)return;const p=active()&&state.connected;state.events.push({protected:p,query:p?'':query,time:new Date().toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit'}),network:state.connected});state.events=state.events.slice(-12);save();$('#events').innerHTML=events();$('#searchResult').innerHTML=`<div class="result"><small>SIMULATED SEARCH RESULTS</small><h3>Results for “${escapeHTML(query)}”</h3><p>${p?'Your search can still work while new tracking and profile sharing are blocked.':'Your search works normally. A new browsing signal has been shared in this fictional network.'}</p></div>`}}
function action(a){if(a==='buy')return purchase();if(a==='start')return start(true);if(a==='network')return network();if(a==='wait'){setView('laptop');toast('Wi-Fi stays on. Private protection is off.');return}if(a==='laptop')return setView('laptop');if(a==='session'){state.view='hub';state.screen='details';return render()}state.screen=a==='home'?'home':a;render()}
function modal(content){$('#modalContent').innerHTML=`<div class="modal-inner"><div class="modal-top"><span>HUSH / PRIVATE HOURS</span><button class="close" id="closeModal" aria-label="Close dialog">×</button></div>${content}</div>`;$('#closeModal').onclick=()=>$('#modal').close();if(!$('#modal').open)$('#modal').showModal();bind()}
function purchase(){if(active()){toast('A private session is already active.');return}if(state.allowance){start(true);return}modal(`<h2>A little more time.<br>Just for you.</h2><p>Your monthly hours renew in 3 days. Until then, add a private hour for your connected home.</p><div class="purchase-card"><div class="price">$3.99<span>ONE-TIME PURCHASE</span></div><div class="purchase-row"><span>Private time</span><strong>60 continuous minutes</strong></div><div class="purchase-row"><span>Connected devices</span><strong>All 11</strong></div><div class="purchase-row"><span>Starts</span><strong>Immediately after payment</strong></div></div><p class="fineprint">Prevents new tracking and profile sharing during this session. Previously collected data and existing profiles will not be removed.</p><button class="primary wide" id="pay">Confirm & start · $3.99</button><button class="secondary" id="notNow">Not now</button><div class="mock-label">Prototype checkout · no real payment</div>`);$('#pay').onclick=()=>{state.purchases++;start(false)};$('#notNow').onclick=()=>$('#modal').close()}
function start(monthly){state.source=monthly?'monthly':'extra';state.end=Date.now()+(monthly?72000:3600)*1000;state.allowance=0;$('#modal').close();render();toast(monthly?'Monthly Private Hours started.':'Private protection is on. Your hour starts now.')}
function network(){modal(`<h2>Your connection.</h2><p>HUSH protects connected devices only while they use its Wi-Fi and Private Hours are active.</p><div class="demo-stack"><button class="${state.connected?'primary':'secondary'}" id="hushNetwork">HUSH Home Wi-Fi ${state.connected?'✓':''}</button><button class="${!state.connected?'primary':'secondary'}" id="otherNetwork">Other Wi-Fi / mobile hotspot ${!state.connected?'✓':''}</button></div>`);$('#hushNetwork').onclick=()=>{state.connected=true;$('#modal').close();render()};$('#otherNetwork').onclick=()=>{state.connected=false;$('#modal').close();render()}}
$('#demoOpen').onclick=()=>{modal(`<h2>Set the scene.</h2><p>Presentation controls for exploring the same household at different moments.</p><div class="demo-stack"><button class="secondary" id="expire">Jump to the last 10 seconds</button><button class="secondary" id="renew">Renew monthly allowance</button><button class="primary" id="reset">Restart · 0 hours remaining</button></div>`);$('#expire').onclick=()=>{if(!active()){toast('Start a private session first.');return}state.end=Date.now()+10000;$('#modal').close();render();toast('Session ends in 10 seconds.')};$('#renew').onclick=()=>{state.end=0;state.allowance=20;state.view='hub';state.screen='home';$('#modal').close();render();toast('New month: 20 shared Private Hours available.')};$('#reset').onclick=()=>{state={end:0,allowance:0,view:'hub',screen:'home',connected:true,events:[],purchases:0,source:'extra'};$('#modal').close();render();toast('Back to the beginning.')}};
$('#guideOpen').onclick=()=>modal(`<h2>One home.<br>Two possible evenings.</h2><div class="guide-step"><strong>01 / Begin at the hub</strong><span>Your household’s 20 Private Hours are used up. Renewal is 3 days away.</span></div><div class="guide-step"><strong>02 / Make a choice</strong><span>Buy one hour, or continue without protection. Explore the connected browser on either path.</span></div><div class="guide-step"><strong>03 / Follow the information</strong><span>Watch new sharing events. Start protection afterwards and notice what stays.</span></div><div class="guide-step"><strong>04 / Try the other evening</strong><span>Restart from Demo controls. Compare the same search with protection on.</span></div><p class="fineprint">This design fiction imagines participating services honouring a paid, time-limited privacy protocol. It does not provide real Wi-Fi protection or process payments.</p>`);
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('.wordmark').onclick=e=>{e.preventDefault();setView('hub')};$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}};
let wasActive=active();setInterval(()=>{const isActive=active();if(wasActive&&!isActive){state.end=0;render();toast('Your Private Hour has ended. Wi-Fi stays connected.');if($('#modal').open)$('#modal').close()}wasActive=isActive;const timer=$('#timer');if(timer&&isActive)timer.textContent=clock();const meter=$('#meterFill');if(meter&&isActive)meter.style.width=seconds()/(state.source==='monthly'?72000:3600)*100+'%';if(state.view==='laptop'){const label=$('.browser-status span');if(label&&isActive&&state.connected)label.textContent='Private protection ON · '+clock()}},1000);render();
